**Issue 3 — No rate limiting on the redirect endpoint**

The file `c:\_Work\Trainings\01_GitHub Copilot Beginner to Pro\linkshortenerproject\app\l\[shortCode]\route.ts` currently has no rate limiting, making it vulnerable to enumeration attacks and DoS.

Current file content:
```typescript
import { NextResponse } from 'next/server';
import { getLinkByShortCode } from '@/data/links';

export async function GET(
  _request: Request,
  { params }: { params: Promise<{ shortCode: string }> },
): Promise<NextResponse> {
  const { shortCode } = await params;
  const link = await getLinkByShortCode(shortCode);

  if (!link) {
    return NextResponse.json({ error: 'Not found' }, { status: 404 });
  }

  return NextResponse.redirect(link.url, { status: 301 });
}
```

**Fix required:** Add an in-memory rate limiter (since no Redis is available) that allows a maximum of 60 requests per minute per IP address. If the limit is exceeded, return a `429 Too Many Requests` response.

Replace the entire file content with this:

```typescript
import { NextResponse } from 'next/server';
import { getLinkByShortCode } from '@/data/links';

// Simple in-memory rate limiter: max 60 requests per minute per IP
const rateLimitMap = new Map<string, { count: number; resetAt: number }>();
const RATE_LIMIT_MAX = 60;
const RATE_LIMIT_WINDOW_MS = 60 * 1000;

function isRateLimited(ip: string): boolean {
  const now = Date.now();
  const entry = rateLimitMap.get(ip);

  if (!entry || now > entry.resetAt) {
    rateLimitMap.set(ip, { count: 1, resetAt: now + RATE_LIMIT_WINDOW_MS });
    return false;
  }

  if (entry.count >= RATE_LIMIT_MAX) {
    return true;
  }

  entry.count += 1;
  return false;
}

export async function GET(
  request: Request,
  { params }: { params: Promise<{ shortCode: string }> },
): Promise<NextResponse> {
  const ip =
    request.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ??
    request.headers.get('x-real-ip') ??
    'unknown';

  if (isRateLimited(ip)) {
    return NextResponse.json(
      { error: 'Too many requests. Please try again later.' },
      { status: 429 },
    );
  }

  const { shortCode } = await params;
  const link = await getLinkByShortCode(shortCode);

  if (!link) {
    return NextResponse.json({ error: 'Not found' }, { status: 404 });
  }

  return NextResponse.redirect(link.url, { status: 301 });
}
```

